CREATE FUNCTION public.guard_interview_analysis_approval() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.interview_sessions; BEGIN PERFORM pg_advisory_xact_lock(710112026); SELECT * INTO s FROM public.interview_sessions WHERE analysis_version_id=NEW.id; IF s.id IS NOT NULL AND NEW.status IN ('in_review','approved') THEN IF NOT public.interview_covered(s.id) OR EXISTS(SELECT 1 FROM public.evidence_conflicts WHERE job_role_id=s.job_role_id AND status='open') THEN RAISE EXCEPTION 'Interview coverage and conflict resolution required'; END IF; IF NEW.status='approved' AND NOT public.has_role(auth.uid(),'hr_reviewer') THEN RAISE EXCEPTION 'Only HR can approve interview analyses'; END IF; END IF; RETURN NEW; END $$; CREATE TRIGGER interview_analysis_gate BEFORE UPDATE ON public.role_analysis_versions FOR EACH ROW EXECUTE FUNCTION public.guard_interview_analysis_approval(); REVOKE ALL ON FUNCTION public.guard_interview_analysis_approval() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.test_interview_rule(test_name text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid:='20000000-0000-0000-0000-000000000003'; result boolean:=false; BEGIN IF test_name='training_modules' THEN RETURN public.interview_required(ARRAY['training'])=ARRAY['A','B','C','D','E','H']; ELSIF test_name='incomplete_coverage' THEN RETURN NOT public.interview_covered(sid); ELSIF test_name='purpose_output' THEN RETURN public.interview_output_allowed(ARRAY['training'],'Training plan','') AND NOT public.interview_output_allowed(ARRAY['training'],'Hiring materials',''); END IF; BEGIN IF test_name='review_gate' THEN UPDATE public.interview_sessions SET status='in_review' WHERE id=sid; ELSIF test_name='draft_gate' THEN INSERT INTO public.interview_outputs(session_id,output_type,content,evidence_ids) VALUES(sid,'Training plan','Test',ARRAY['20000000-0000-0000-0000-000000000011']::uuid[]); ELSIF test_name='source_role' THEN INSERT INTO public.interview_answers(session_id,source_id,module,values,evidence_id) VALUES(sid,'20000000-0000-0000-0000-000000000004','A','{}','10000000-0000-0000-0000-000000000001'); ELSIF test_name='evidence_immutable' THEN UPDATE public.evidence_items SET excerpt='Changed' WHERE id='20000000-0000-0000-0000-000000000011'; ELSIF test_name='importance_range' THEN INSERT INTO public.interview_answers(session_id,source_id,module,values,evidence_id) VALUES(sid,'20000000-0000-0000-0000-000000000004','B','{"2":"6","4":"30"}','20000000-0000-0000-0000-000000000011'); ELSE RETURN false; END IF; RAISE EXCEPTION 'Probe write unexpectedly succeeded' USING ERRCODE='P0002'; EXCEPTION WHEN SQLSTATE 'P0002' THEN result:=false; WHEN OTHERS THEN result:=true; END; RETURN result; END $$; REVOKE ALL ON FUNCTION public.test_interview_rule(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.test_interview_rule(text) TO service_role;